<?php require __DIR__.'/bootstrap.php';$success=false;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$phone=trim((string)($_POST['phone']??''));$description=trim((string)($_POST['description']??''));if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$phone||!$description){$error='Please complete all required fields.';}else{$req=['id'=>bin2hex(random_bytes(8)),'reference'=>'CR-'.strtoupper(bin2hex(random_bytes(4))),'created_at'=>date(DATE_ATOM),'name'=>$name,'email'=>$email,'phone'=>$phone,'occasion'=>trim((string)($_POST['occasion']??'')),'flavour'=>trim((string)($_POST['flavour']??'')),'size'=>trim((string)($_POST['size']??'')),'budget'=>trim((string)($_POST['budget']??'')),'required_date'=>trim((string)($_POST['required_date']??'')),'description'=>$description,'colours'=>trim((string)($_POST['colours']??'')),'custom_message'=>trim((string)($_POST['custom_message']??'')),'status'=>'New request','image'=>''];if(isset($_FILES['inspiration'])&&$_FILES['inspiration']['error']===UPLOAD_ERR_OK){$f=$_FILES['inspiration'];if($f['size']>5*1024*1024)$error='Image must be 5 MB or smaller.';else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';if(!$ext)$error='Upload a JPG, PNG, or WebP image.';else{$dir=PRIVATE_DIR.'/uploads';if(!is_dir($dir))mkdir($dir,0750,true);$file=$req['id'].'.'.$ext;if(move_uploaded_file($f['tmp_name'],$dir.'/'.$file))$req['image']=$file;}}}if(!$error){$requests=read_json('custom-requests.json',[]);$requests[]=$req;write_json('custom-requests.json',$requests);add_notification('New custom cake request',$req['reference'].' from '.$name,'custom');$success=true;}}}site_header('Custom cake request'); ?>
